# Verify the final venmo friends list matches phone friends
venmo_friends_final = []
page_index = 0
while True:
    resp = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=20)
    if not resp:
        break
    venmo_friends_final.extend(resp)
    if len(resp) < 20:
        break
    page_index += 1

venmo_final_emails = {f['email'] for f in venmo_friends_final}
phone_friend_emails = {f['email'] for f in phone_friends}

print("Venmo final emails:", sorted(venmo_final_emails))
print("Phone friend emails:", sorted(phone_friend_emails))
print("Match:", venmo_final_emails == phone_friend_emails)

