            # Check if all file artists are in detail artists (order may differ)
            if all(fa in detail_artists for fa in file_artists) and len(file_artists) == len(detail_artists):
                found = sid
                break
    if found is not None:
        matched_song_ids.append(found)
        print(f"Matched: {title} -> song_id {found}")
    else:
        print(f"NOT FOUND: {title}")

