# Verify we have processed all playlists and that the new playlist contains all archived songs
# Fetch all playlists (paginate if needed)
all_playlists = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=50)
    if not page or not page.get("playlists"):
        break
    all_playlists.extend(page["playlists"])
    if len(page["playlists"]) < 50:
        break
    page_index += 1

# Check each playlist (except 654) for any remaining archived songs
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
remaining = []
for pl in all_playlists:
    if pl["playlist_id"] == 654:
        continue
    for sid in pl.get("song_ids", []):
        if sid in archived_song_ids:
            remaining.append((pl["playlist_id"], pl["title"], sid))

print("Remaining archived songs in other playlists:", remaining)

# Check the new playlist's contents
new_playlist = apis.spotify.show_playlist(playlist_id=654, access_token=login_result["access_token"])
print("New playlist songs:", new_playlist.get("song_ids", []))

