# Fetch details for all unique songs to identify matches.
song_details = {}
for sid in sorted(all_song_ids):
    try:
        details = apis.spotify.show_song(song_id=sid)
        song_details[sid] = details
    except Exception as e:
        print(f"Error fetching song {sid}: {e}")
print(f"Fetched {len(song_details)} songs")
# Print a few to verify format
for sid in sorted(song_details)[:5]:
    d = song_details[sid]
    print(sid, d['title'], [a['name'] for a in d['artists']])

