# We need to find the song IDs for all songs in the list. Let's search for each song and collect the song_id.
# We'll use the query with title and all artists to be specific.
song_ids = {}
for song in songs_to_archive:
    title = song['title']
    artists = song['artists']
    query = title + " " + " ".join(artists)
    result = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find the first result that matches title and all artists
    found = None
    for item in result:
        if item['title'].lower() == title.lower():
            item_artists = [a['name'].lower() for a in item['artists']]
            if all(any(a.lower() in item_artists for a in artists) for a in artists):
                found = item
                break
    if found:
        song_ids[found['song_id']] = song
        print(f"Found: {title} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {title}")

print("\nTotal song_ids found:", len(song_ids))

