# Let's inspect all playlists to see which target songs are present.
# We'll collect the song IDs for each playlist.
playlist_songs = {}
for pid in playlist_ids:
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    song_ids = [song['id'] for song in pl['songs']]
    playlist_songs[pid] = song_ids
    print(f"Playlist {pid}: {song_ids}")

# Now identify which target songs are in each playlist
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
for pid, song_ids in playlist_songs.items():
    present = [sid for sid in song_ids if sid in target_song_ids]
    print(f"Playlist {pid} contains target songs: {present}")

