# Search for all songs and collect release dates
import json

# Define a function to find the exact song match
def find_song_match(search_results, expected_title, expected_artists):
    for song in search_results:
        if song['title'].lower() == expected_title.lower():
            song_artists = [a['name'] for a in song['artists']]
            # Check if all expected artists are in song_artists and vice versa
            if set(song_artists) == set(expected_artists):
                return song
    return None

# Loop through songs to update
release_dates = {}
for song in songs_to_update:
    title = song['title']
    artists = song['artists']
    result = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    match = find_song_match(result, title, artists)
    if match:
        release_dates[title] = match['release_date']
        print(f"Found: {title} -> {match['release_date']}")
    else:
        print(f"NOT FOUND: {title} by {artists}")

print("\nAll release dates collected:")

