# Process all songs to get release months
release_months = {}
for song in songs_todo:
    title = song['title']
    artists = song['artists']
    month = find_release_month(title, artists, spotify_token)
    if month:
        release_months[title] = month
        print(f"{title}: {month}")
    else:
        print(f"NOT FOUND: {title}")

# Parse the note content to extract lines with RELEASED_AT TODO
note_content = note['content']
lines = note_content.split('\n')
todo_lines = []
for line in lines:
    if 'RELEASED_AT TODO' in line:
        todo_lines.append(line)
print(f"Found {len(todo_lines)} lines with TODO")
for l in todo_lines:
    print(l)

# Search for "Lonely Skies"
result = apis.spotify.search_songs(query='Lonely Skies', access_token=spotify_token, page_limit=20)
for song in result:
    if song['title'] == 'Lonely Skies':
        print(song['song_id'], song['title'], song['artists'][0]['name'], song['release_date'])
        break

# Search for "Caught in a Web of Lies"
result = apis.spotify.search_songs(query='Caught in a Web of Lies', access_token=spotify_token, page_limit=20)
