# Parse the note content to extract songs with TODO
content = note['content']
lines = content.split('\n')
songs_todo = []
for line in lines:
    if line.startswith('- '):
        # Extract song and artist part before RELEASED_AT
        if 'RELEASED_AT TODO' in line:
            # Remove the prefix "- " and the suffix " RELEASED_AT TODO"
            song_artist = line[2:].replace(' RELEASED_AT TODO', '')
            # Split on " BY " to get song and artists
            if ' BY ' in song_artist:
                song_title, artists_str = song_artist.split(' BY ', 1)
                songs_todo.append((song_title.strip(), artists_str.strip(), line))
            else:
                print(f"Unexpected format: {line}")
print(f"Found {len(songs_todo)} songs with TODO")
for s in songs_todo:
    print(s)

