steps.code:
# Search for each song and extract release date.
release_dates = {}
for title, artists in songs_todo:
    # Build query: title + first artist (or all artists concatenated)
    artist_part = artists.replace(', ', '')
    query = title.replace(' ', '') + artist_part.replace(' ', '')
    results = apis.spotify.search_songs(query=query)
    # Find matching song
    found = None
    for song in results:
        if song['title'].lower() == title.lower():
            # Check artists match (at least one artist matches)
            song_artists = [a['name'] for a in song['artists']]
            # Check if all artists in our list are present (or at least one)
            our_artists = [a.strip() for a in artists.split(',')]
            if all(any(our.lower() == sa.lower() for sa in song_artists) for our in our_artists):
                found = song
                break
    if found:
        release_dates[title] = found['release_date']
        print(f"{title} -> {found['release_date']}")
    else:
        print(f"NOT FOUND: {title}")

